graphql.query:
query GetStatus {
  status {
    isIndexing
    lastBlockNumber
    errorCount
    uptime
  }
}

query GetStats {
  stats {
    totalEvents
    totalTransfers
    totalSwaps
    latestBlock
  }
}

query GetTransferEvents($first: Int) {
  events(first: $first, type: ERC20_TRANSFER) {
    ... on ERC20Transfer {
      id
      blockNumber
      blockTimestamp
      transactionHash
      from
      to
      value
      tokenAddress
    }
  }
}

query GetSwapEvents($first: Int) {
  events(first: $first, type: SWAP) {
    ... on Swap {
      id
      blockNumber
      blockTimestamp
      transactionHash
      poolAddress
      sender
      recipient
      amount0In
      amount1In
      amount0Out
      amount1Out
    }
  }
}

query GetRecentTransfers($first: Int) {
  transfers(first: $first) {
    id
    blockNumber
    blockTimestamp
    transactionHash
    from
    to
    value
    tokenAddress
  }
}

query GetTransfersByAddress($to: String, $first: Int) {
  transfers(to: $to, first: $first) {
    id
    blockNumber
    blockTimestamp
    transactionHash
    from
    to
    value
    tokenAddress
  }
}

query GetTransfersPaginated($first: Int, $after: String) {
  transfers(first: $first, after: $after) {
    id
    blockNumber
    blockTimestamp
    transactionHash
    from
    to
    value
    tokenAddress
  }
}
